{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Rates Watch Data",
    "url": "http://localhost:7803",
    "widgets_json": {
      "auction_calendar": {
        "name": "Auction Calendar",
        "description": "Upcoming treasury auctions.",
        "endpoint": "/auction-calendar",
        "type": "table",
        "gridData": {"w": 20, "h": 9},
        "staleTime": 900000,
        "data": {
          "table": {
            "columnsDefs": [
              {"field": "date", "headerName": "Date", "cellDataType": "dateString"},
              {"field": "security", "headerName": "Security", "cellDataType": "text"},
              {"field": "size_bn", "headerName": "Size ($B)", "cellDataType": "number"}
            ]
          }
        }
      },
      "yield_curve": {
        "name": "Yield Curve",
        "description": "Plotly treasury yield curve snapshot.",
        "endpoint": "/yield-curve",
        "type": "chart",
        "gridData": {"w": 20, "h": 9},
        "staleTime": 900000,
        "data": {
          "raw": true
        }
      }
    },
    "apps_json": [
      {
        "name": "Rates Desk",
        "description": "Auctions and the curve.",
        "tabs": {
          "auctions": {
            "id": "auctions",
            "name": "Auctions",
            "layout": [
              {"i": "auction_calendar", "x": 0, "y": 0, "w": 20, "h": 9}
            ]
          },
          "curve": {
            "id": "curve",
            "name": "Curve",
            "layout": [
              {"i": "yield_curve", "x": 0, "y": 0, "w": 20, "h": 9}
            ]
          }
        }
      }
    ]
  }
}
